    @Test
    void modernOwnerReusesItsNormallyPreparedExactFactAcrossCleanReopen(@TempDir Path evidence) throws Exception {
        Path directory = evidence.resolve("modern");
        LmdbRuntimeFeedbackDescriptor descriptor;
        SailRepository first = open(directory);
        try {
            LmdbStore store = (LmdbStore) first.getSail();
            try (var connection = first.getConnection()) {
                connection.begin();
                for (int index = 0; index < 11; index++) {
                    connection.add(store.getValueFactory().createIRI("urn:modern-operator:s:" + index),
                            CanonicalIriCompatibilityProcess.PREDICATE,
                            store.getValueFactory().createIRI("urn:modern-operator:o:" + index));
                }
                connection.commit();
            }
            StoreProperties policy = new StoreProperties(directory.toFile());
            assertTrue(policy.load());
            assertNotNull(policy.savedStoreId(), "this freshly created modern store has its normal property UUID receipt");
            assertTrue(store.forceFlushSketchEstimator());
            assertEquals(org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability.READY,
                    store.rebuildFrontierStatistics().availability());
            try (Compiled compiled = compile(store)) {
                assertEquals(11, compiled.evaluateCount());
                var contract = compiled.population.getRuntimeFeedbackContract();
                assertNotNull(contract);
                assertTrue(contract.admits(RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE));
                descriptor = assertInstanceOf(LmdbRuntimeFeedbackDescriptor.class, contract.descriptor());
                var feedback = compiled.statistics.estimatorRuntime().feedback();
                assertEquals(11.0d, feedback.exactCardinalityFact(descriptor.logicalKey(), descriptor.applicability()), 0.0d);
                feedback.persistIfDirty();
            }
            store.getBackingStore().getSketchBasedJoinEstimator().persistIfDirty();
        } finally { first.shutDown(); }
        Path file = directory.resolve("join-estimator.rjes.operators");
        assertTrue(Files.isRegularFile(file));
        byte[] persisted = Files.readAllBytes(file);
        SailRepository second = open(directory);
        try {
            LmdbStore store = (LmdbStore) second.getSail();
            assertArrayEquals(persisted, Files.readAllBytes(file));
            try (Compiled compiled = compile(store)) {
                var feedback = compiled.statistics.estimatorRuntime().feedback();
                assertEquals(11.0d, feedback.exactCardinalityFact(descriptor.logicalKey(), descriptor.applicability()),
                        0.0d, "modern identity/stamp validation retains normal cross-owner persisted reuse");
                assertEquals(11, compiled.evaluateCount());
            }
        } finally { second.shutDown(); }
    }

    private record Compiled(SailDataset dataset, LmdbEvaluationStatistics statistics, StatementPattern population,
            QueryEvaluationStep step) implements AutoCloseable {
        int evaluateCount() {
            try (var rows = step.evaluate(EmptyBindingSet.getInstance())) { return QueryResults.asList(rows).size(); }
        }
        @Override public void close() { dataset.close(); }
    }
    private static Compiled compile(LmdbStore store) {
        SailDataset dataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
        try {
            var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
            var pair = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
            assertTrue(pair.pinnedReadTxn().isPresent());
            assertTrue(pair.pinnedValueSnapshot().isPresent());
            assertSame(pair.pinnedValueSnapshot().orElseThrow().valueStore()
                    .valuePreparer(pair.pinnedValueSnapshot().orElseThrow()), source.getValuePreparer(),
                    "the real single-plane source owns the optimizer's complete paired preparer");
            var statistics = (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
            var strategy = assertInstanceOf(LmdbEvaluationStrategy.class, store.getConnectionEvaluationStrategyFactory()
                    .createEvaluationStrategy(null, source, statistics, store.getQueryExecutionPolicy()));
            strategy.setTrackResultSize(true);
            TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
            TupleExpr optimized = strategy.optimize(parsed, statistics, EmptyBindingSet.getInstance());
            QueryEvaluationStep step = strategy.precompile(optimized);
            assertTrue(statistics.feedbackPublicationAllowed());
            var authority = LmdbFeedbackReadAuthority.capture(statistics.estimatorRuntime(), source, null);
            assertNotNull(authority); assertTrue(authority.isCurrent());
            List<StatementPattern> populations = new ArrayList<>();
            optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
                @Override public void meet(StatementPattern pattern) { populations.add(pattern); super.meet(pattern); }
            });
            assertEquals(1, populations.size(), "the normal optimizer retains one actual complete pattern population");
            return new Compiled(dataset, statistics, populations.getFirst(), step);
        } catch (RuntimeException | Error failure) { dataset.close(); throw failure; }
    }
